window.__JBTOP=[["UNSETTLED ATLAS · 05 THUNDER RIGS — how space becomes normal","terrarium","https://hartswf0.github.io/terrarium/unset-04-hartsoe.html","6eb6a815e04d","Gem","A synthetic place for testing how space becomes normal. Entering it changes it; its instruments alter what they measure. Part of the Unsettled Atlas."],["TIE Build","tractor-dce-gyo","https://hartswf0.github.io/tractor-dce-gyo/tie-game.html","bb6dbefe79da","Gem","A 3D game, played with keys or touch, with sound and shaders. It connects to others online and lets you export what you make."],["THUNDER RIGS | HELLO WORLD 005","thunder-rigs","https://hartswf0.github.io/thunder-rigs/","5a0662dbda80","Gem","A 3D game, played with keys or touch, with sound, the camera, voice and shaders. It talks to a language model, connects to others online, remembers your progress, lets you export what you make and opens your files."],["MONTE · BOLT // Slide Presentation & Comparison Instrument","worldful","https://hartswf0.github.io/worldful/PROP-911/monte-bolt.html","1d0226465f69","Gem","A prompt is not a command sent to a machine. A prompt is a language-game."],["TERMINUS POSE 80 · many bodies, one world","pretext-field","https://hartswf0.github.io/pretext-field/terminus-pose-82.html","0692e234870d","Gem","Many bodies, many paper aircraft, one real planet. Scan the wall; your phone camera turns your pose into a plane, then into the mail you release."],["FÚTBOLMAS · Tactical Mind V10","momsaic","https://hartswf0.github.io/momsaic/futbolmas-tactical-academy-v13-full.html","b5b83b1d9095","Gem","Un código. Un QR. Una cancha en la sala."],["ORCA // BLUE_HOUR_LIDAR_v19_CINEMATIC_SOULS","jdb-ripple-remix","https://hartswf0.github.io/jdb-ripple-remix/blue-orchid-cinematic-souls.html","ff0c6ce5de8e","Gem","A game, played with keys or touch, with sound and voice. It talks to a language model and remembers your progress."],["ELO COPA 26 — The World Reads Here","ripples","https://hartswf0.github.io/ripples/elo-copa-26-live-links%20%282%29.html","c0427c1c403c","Gem","ELO COPA 26 — the mobile-first ELO (un)supervised 2026 conference schedule, speaker directory, personal lineup and time-zone-aware match center."],["Gunnar City Builder","gunnars-depot.html","https://hartswf0.github.io/gunnars-depot.html/city-builder-game.html","81ffc4ceb2f1","Gem","Roads, zones, utilities, parks, and taxes are holding together."],["LEGOS Tetrad Analyzer - McLuhan's Four Laws","the-fork","https://hartswf0.github.io/the-fork/RAILWAY%20GAME/thousand-tetrad-00.html","65b1be98cbf3","Gem","A 3D game, played with keys or touch, with sound. It talks to a language model, remembers your progress, lets you export what you make and opens your files. Tended across 3 versions."],["Algorithmic Reflections — Mirror Presenter (TDiff Boxes)","encoded-power","https://hartswf0.github.io/encoded-power/ar-04.html","48ca8ff018a2","Gem","This demo uses your device's camera to detect motion and navigate slides. No video data leaves your device."],["HALFWORLD — Integrated Atlantis Halftrack Studio","halfworld","https://hartswf0.github.io/halfworld/halfworld-atlantis-halftrack-integrated.html","c46c08b2b884","Gem","A game, played with keys or touch, with the camera and voice. It talks to a language model, remembers your progress, lets you export what you make and opens your files. Tended across 4 versions."]];
